def _env_int(name: str, default: int) -> int:
    v = os.environ.get(name)
    if v is None:
        return default
    try:
        return int(v)
    except Exception:
        return default


def _env_str(name: str, default: str) -> str:
    v = os.environ.get(name)
    if v is None:
        return default
    return str(v)


def _env_list(name: str, default: str) -> List[str]:
    raw = os.environ.get(name, default)
    parts = [p.strip() for p in str(raw).split(",")]
    return [p for p in parts if p]


MAX_REQUEST_BYTES = _env_int("MAX_REQUEST_BYTES", 2_000_000)
MAX_MESSAGES = _env_int("MAX_MESSAGES", 2000)
MAX_MESSAGE_CHARS = _env_int("MAX_MESSAGE_CHARS", 200_000)
STATIC_INDEX_PATH = _env_str("STATIC_INDEX_PATH", "index.html")
ALLOWED_ORIGINS = _env_list("ALLOWED_ORIGINS", "*")
HOST = _env_str("HOST", "0.0.0.0")
PORT = _env_int("PORT", int(os.environ.get("PORT", "8000") or "8000"))
LOG_LEVEL = _env_str("LOG_LEVEL", "info")

MODEL_ID = "zai-glm-4.7"
MAX_COMPLETION_TOKENS = 65000
TEMPERATURE = 1
TOP_P = 0.95
CLEAR_THINKING = False
DISABLE_REASONING = False

CEREBRAS_API_HOST = "api.cerebras.ai"
CEREBRAS_CHAT_PATH = "/v1/chat/completions"


def _load_api_keys() -> List[str]:
    keys: List[str] = []
    packed = os.environ.get("CEREBRAS_API_KEYS")
    if packed:
        keys.extend([k.strip() for k in packed.split(",") if k.strip()])
    for i in range(1, 101):
        k = os.environ.get(f"CEREBRAS_API_KEY_{i}")
        if k and str(k).strip():
            keys.append(str(k).strip())
    single = os.environ.get("CEREBRAS_API_KEY")
    if single and str(single).strip():
        keys.append(str(single).strip())
    seen = set()
    out: List[str] = []
    for k in keys:
        if k not in seen:
            seen.add(k)
            out.append(k)
    return out


def _json_dumps(obj: Any) -> bytes:
    return json.dumps(obj, ensure_ascii=False,
                      separators=(",", ":")).encode("utf-8")


def _now() -> float:
    return time.time()


def _parse_retry_after(headers: Dict[str, str]) -> Optional[float]:
    ra = headers.get("retry-after") or headers.get(
        "Retry-After") or headers.get("RETRY-AFTER")
    if not ra:
        return None
    try:
        return float(str(ra).strip())
    except Exception:
        return None


class ApiKeyPool:

    def __init__(self, api_keys: List[str]) -> None:
        if not api_keys:
            raise RuntimeError("No Cerebras API keys found in environment")
        self._lock = threading.Lock()
        self._keys = list(api_keys)
        self._cooldown_until: Dict[str, float] = {k: 0.0 for k in self._keys}
        self._exhausted_until: Dict[str, float] = {k: 0.0 for k in self._keys}
        self._disabled: Dict[str, bool] = {k: False for k in self._keys}
        self._rr = 0

    def acquire(self) -> str:
        with self._lock:
            n = len(self._keys)
            now = _now()
            for _ in range(n):
                idx = self._rr % n
                self._rr += 1
                k = self._keys[idx]
                if self._disabled.get(k, False):
                    continue
                if now < self._cooldown_until.get(k, 0.0):
                    continue
                if now < self._exhausted_until.get(k, 0.0):
                    continue
                return k
            earliest: Optional[float] = None
            for k in self._keys:
                if self._disabled.get(k, False):
                    continue
                t = max(self._cooldown_until.get(k, 0.0),
                        self._exhausted_until.get(k, 0.0))
                if earliest is None or t < earliest:
                    earliest = t
            if earliest is None:
                raise RuntimeError("All Cerebras API keys are disabled")
            wait = max(0.0, earliest - now)
            raise RuntimeError(
                f"No available Cerebras API keys (cooldown), retry after {wait:.2f}s"
            )

    def mark_rate_limited(self, api_key: str,
                          seconds: Optional[float]) -> None:
        backoff = float(
            seconds) if seconds is not None and seconds > 0 else 5.0
        until = _now() + backoff
        with self._lock:
            cur = self._cooldown_until.get(api_key, 0.0)
            if until > cur:
                self._cooldown_until[api_key] = until

    def mark_exhausted(self, api_key: str, seconds: Optional[float]) -> None:
        backoff = float(
            seconds) if seconds is not None and seconds > 0 else 86400.0
        until = _now() + backoff
        with self._lock:
            cur = self._exhausted_until.get(api_key, 0.0)
            if until > cur:
                self._exhausted_until[api_key] = until

    def disable(self, api_key: str) -> None:
        with self._lock:
            self._disabled[api_key] = True

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            now = _now()
            total = len(self._keys)
            disabled = sum(1 for k in self._keys
                           if self._disabled.get(k, False))
            available = 0
            for k in self._keys:
                if self._disabled.get(k, False):
                    continue
                if now < self._cooldown_until.get(k, 0.0):
                    continue
                if now < self._exhausted_until.get(k, 0.0):
                    continue
                available += 1
            return {
                "total": total,
                "available": available,
                "disabled": disabled
            }


API_KEYS = _load_api_keys()
pool = ApiKeyPool(API_KEYS)


def _log(msg: str) -> None:
    if LOG_LEVEL.lower() == "debug":
        try:
            print(msg, flush=True)
        except Exception:
            pass


def _origin_allowed(origin: Optional[str]) -> Optional[str]:
    if not origin:
        return "*" if ALLOWED_ORIGINS == ["*"] else None
    if ALLOWED_ORIGINS == ["*"]:
        return "*"
    for o in ALLOWED_ORIGINS:
        if o == origin:
            return origin
    return None


def _read_body(handler: BaseHTTPRequestHandler) -> bytes:
    cl = handler.headers.get("Content-Length")
    if cl is None:
        body = handler.rfile.read(MAX_REQUEST_BYTES + 1)
        if len(body) > MAX_REQUEST_BYTES:
            raise ValueError("request too large")
        return body
    try:
        n = int(cl.strip())
    except Exception:
        raise ValueError("invalid content-length")
    if n < 0:
        raise ValueError("invalid content-length")
    if n > MAX_REQUEST_BYTES:
        raise ValueError("request too large")
    body = handler.rfile.read(n)
    if body is None:
        return b""
    return body


def _parse_chat_request(
        raw: bytes) -> Tuple[List[Dict[str, str]], Optional[str]]:
    if raw is None or len(raw) == 0:
        raise ValueError("empty body")
    if len(raw) > MAX_REQUEST_BYTES:
        raise ValueError("request too large")
    try:
        data = json.loads(raw.decode("utf-8"))
    except Exception:
        raise ValueError("invalid json")
    if not isinstance(data, dict):
        raise ValueError("invalid body")
    msgs = data.get("messages")
    user = data.get("user")
    if msgs is None or not isinstance(msgs, list):
        raise ValueError("messages must be a list")
    if len(msgs) > MAX_MESSAGES:
        raise ValueError("too many messages")
    out: List[Dict[str, str]] = [{
        "role": "system",
        "content": "mindig magyarul válaszolj"
    }]
    for m in msgs:
        if not isinstance(m, dict):
            raise ValueError("message must be an object")
        role = m.get("role")
        content = m.get("content")
        if role not in ("system", "user", "assistant"):
            raise ValueError("invalid role")
        if content is None:
            content = ""
        if not isinstance(content, str):
            raise ValueError("content must be a string")
        if len(content) > MAX_MESSAGE_CHARS:
            raise ValueError("message too large")
        out.append({"role": str(role), "content": content})
    user_str: Optional[str]
    if user is None:
        user_str = None
    else:
        user_str = str(user)
    return out, user_str


def _http_error_json(handler: BaseHTTPRequestHandler, status: int, code: str,
                     detail: Any, origin: Optional[str]) -> None:
    payload = {"error": code, "detail": detail}
    body = _json_dumps(payload)
    handler.send_response(status)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Content-Length", str(len(body)))
    handler.send_header("Connection", "close")
    if origin is not None:
        handler.send_header("Access-Control-Allow-Origin", origin)
        handler.send_header("Vary", "Origin")
        handler.send_header("Access-Control-Allow-Credentials", "true")
        handler.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
        handler.send_header("Access-Control-Allow-Headers",
                            "Content-Type,Authorization")
    handler.end_headers()
    handler.wfile.write(body)


def _http_json(handler: BaseHTTPRequestHandler, status: int, payload: Any,
               origin: Optional[str]) -> None:
    body = _json_dumps(payload)
    handler.send_response(status)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Content-Length", str(len(body)))
    handler.send_header("Connection", "close")
    if origin is not None:
        handler.send_header("Access-Control-Allow-Origin", origin)
        handler.send_header("Vary", "Origin")
        handler.send_header("Access-Control-Allow-Credentials", "true")
        handler.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
        handler.send_header("Access-Control-Allow-Headers",
                            "Content-Type,Authorization")
    handler.end_headers()
    handler.wfile.write(body)


def _http_file(handler: BaseHTTPRequestHandler, path: str, content_type: str,
               origin: Optional[str]) -> None:
    try:
        with open(path, "rb") as f:
            body = f.read()
    except Exception:
        handler.send_response(404)
        handler.send_header("Connection", "close")
        if origin is not None:
            handler.send_header("Access-Control-Allow-Origin", origin)
            handler.send_header("Vary", "Origin")
            handler.send_header("Access-Control-Allow-Credentials", "true")
            handler.send_header("Access-Control-Allow-Methods",
                                "GET,POST,OPTIONS")
            handler.send_header("Access-Control-Allow-Headers",
                                "Content-Type,Authorization")
        handler.end_headers()
        return
    handler.send_response(200)
    handler.send_header("Content-Type", content_type)
    handler.send_header("Content-Length", str(len(body)))
    handler.send_header("Connection", "close")
    if origin is not None:
        handler.send_header("Access-Control-Allow-Origin", origin)
        handler.send_header("Vary", "Origin")
        handler.send_header("Access-Control-Allow-Credentials", "true")
        handler.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
        handler.send_header("Access-Control-Allow-Headers",
                            "Content-Type,Authorization")
    handler.end_headers()
    handler.wfile.write(body)


def _send_chunk(handler: BaseHTTPRequestHandler, data: bytes) -> None:
    if data is None:
        return
    if len(data) == 0:
        return
    size = f"{len(data):X}\r\n".encode("ascii")
    handler.wfile.write(size)
    handler.wfile.write(data)
    handler.wfile.write(b"\r\n")
    handler.wfile.flush()


def _send_keepalive(handler: BaseHTTPRequestHandler) -> None:
    _send_chunk(handler, b" ")


def _end_chunks(handler: BaseHTTPRequestHandler) -> None:
    try:
        handler.wfile.write(b"0\r\n\r\n")
        handler.wfile.flush()
    except Exception:
        pass


def _cerebras_stream_request(
    api_key: str, messages: List[Dict[str, str]], user: Optional[str]
) -> Tuple[int, Dict[str, str], http.client.HTTPResponse]:
    payload: Dict[str, Any] = {
        "model": MODEL_ID,
        "messages": messages,
        "stream": True,
        "max_completion_tokens": MAX_COMPLETION_TOKENS,
        "temperature": TEMPERATURE,
        "top_p": TOP_P,
        "clear_thinking": CLEAR_THINKING,
        "disable_reasoning": DISABLE_REASONING,
    }
    if user is not None:
        payload["user"] = user
    body = _json_dumps(payload)
    conn = http.client.HTTPSConnection(CEREBRAS_API_HOST, timeout=60)
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "User-Agent": "replit-python-stream-client",
    }
    conn.request("POST", CEREBRAS_CHAT_PATH, body=body, headers=headers)
    resp = conn.getresponse()
    resp_headers_list = resp.getheaders()
    resp_headers: Dict[str, str] = {}
    for k, v in resp_headers_list:
        if k:
            resp_headers[str(k)] = str(v) if v is not None else ""
    return resp.status, resp_headers, resp


def _is_failover_status(status: int) -> bool:
    if status in (401, 403, 402, 429):
        return True
    if status >= 500:
        return True
    return False


def _mark_key_on_status(api_key: str, status: int, headers: Dict[str,
                                                                 str]) -> None:
    ra = _parse_retry_after(headers)
    if status == 429:
        pool.mark_rate_limited(api_key, ra)
        return
    if status == 402:
        pool.mark_exhausted(api_key, ra)
        return
    if status in (401, 403):
        pool.disable(api_key)
        return


def _read_error_body(resp: http.client.HTTPResponse,
                     limit: int = 65536) -> str:
    try:
        data = resp.read(limit + 1)
    except Exception:
        return ""
    if not data:
        return ""
    if len(data) > limit:
        data = data[:limit]
    try:
        return data.decode("utf-8", errors="replace")
    except Exception:
        return ""


def _extract_stream_delta_content(data_obj: Any) -> Optional[str]:
    if not isinstance(data_obj, dict):
        return None
    choices = data_obj.get("choices")
    if not isinstance(choices, list) or not choices:
        return None
    c0 = choices[0]
    if not isinstance(c0, dict):
        return None
    delta = c0.get("delta")
    if not isinstance(delta, dict):
        return None
    content = delta.get("content")
    if isinstance(content, str) and content:
        return content
    return None


def _stream_chat_to_client(handler: BaseHTTPRequestHandler,
                           messages: List[Dict[str, str]], user: Optional[str],
                           origin: Optional[str]) -> None:
    last_error: Optional[str] = None
    attempts = max(1, len(API_KEYS))
    api_key_used: Optional[str] = None
    status: Optional[int] = None
    headers: Dict[str, str] = {}
    resp: Optional[http.client.HTTPResponse] = None

    for _ in range(attempts):
        api_key = pool.acquire()
        api_key_used = api_key
        try:
            st, hdrs, r = _cerebras_stream_request(api_key, messages, user)
            status = st
            headers = hdrs
            resp = r
            if status == 200:
                break
            _mark_key_on_status(api_key, status, headers)
            body_txt = _read_error_body(resp)
            if _is_failover_status(status):
                last_error = body_txt or f"upstream status {status}"
                try:
                    resp.close()
                except Exception:
                    pass
                resp = None
                continue
            last_error = body_txt or f"upstream status {status}"
            break
        except Exception as e:
            last_error = str(e)
            pool.mark_rate_limited(api_key, 2.0)
            resp = None
            continue

    if resp is None or status != 200:
        _http_error_json(handler, 502, "upstream_error", last_error
                         or "unknown upstream error", origin)
        return

    handler.send_response(200)
    handler.send_header("Content-Type", "text/plain; charset=utf-8")
    handler.send_header("Cache-Control", "no-cache, no-transform")
    handler.send_header("Connection", "keep-alive")
    handler.send_header("X-Accel-Buffering", "no")
    handler.send_header("Transfer-Encoding", "chunked")
    if origin is not None:
        handler.send_header("Access-Control-Allow-Origin", origin)
        handler.send_header("Vary", "Origin")
        handler.send_header("Access-Control-Allow-Credentials", "true")
        handler.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
        handler.send_header("Access-Control-Allow-Headers",
                            "Content-Type,Authorization")
    handler.end_headers()

    try:
        resp.fp.raw._sock.settimeout(60)  # type: ignore[union-attr]
    except Exception:
        pass

    last_send = _now()
    event_data_lines: List[bytes] = []

    try:
        while True:
            line = resp.readline()
            if not line:
                break

            now = _now()
            if now - last_send >= 10.0:
                _send_keepalive(handler)
                last_send = now

            if line in (b"\n", b"\r\n"):
                if event_data_lines:
                    joined = b"\n".join(event_data_lines).strip()
                    event_data_lines = []
                    if joined == b"[DONE]":
                        break
                    try:
                        obj = json.loads(joined.decode("utf-8"))
                    except Exception:
                        continue
                    chunk_text = _extract_stream_delta_content(obj)
                    if chunk_text:
                        _send_chunk(
                            handler, chunk_text.encode("utf-8",
                                                       errors="ignore"))
                        last_send = _now()
                continue

            if line.startswith(b"data:"):
                data_part = line[5:].strip()
                if data_part:
                    event_data_lines.append(data_part)
                continue

        if event_data_lines:
            joined = b"\n".join(event_data_lines).strip()
            if joined and joined != b"[DONE]":
                try:
                    obj = json.loads(joined.decode("utf-8"))
                    chunk_text = _extract_stream_delta_content(obj)
                    if chunk_text:
                        _send_chunk(
                            handler, chunk_text.encode("utf-8",
                                                       errors="ignore"))
                except Exception:
                    pass

        _end_chunks(handler)
    except (BrokenPipeError, ConnectionResetError):
        try:
            if api_key_used is not None:
                pool.mark_rate_limited(api_key_used, 1.0)
        except Exception:
            pass
        try:
            _end_chunks(handler)
        except Exception:
            pass
    except socket.timeout:
        try:
            if api_key_used is not None:
                pool.mark_rate_limited(api_key_used, 2.0)
        except Exception:
            pass
        try:
            _end_chunks(handler)
        except Exception:
            pass
    except Exception as e:
        _log(f"stream_error: {e}")
        try:
            if api_key_used is not None:
                pool.mark_rate_limited(api_key_used, 2.0)
        except Exception:
            pass
        try:
            _end_chunks(handler)
        except Exception:
            pass
    finally:
        try:
            resp.close()
        except Exception:
            pass


class AppHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "CerebrasProxy/1.0"

    def log_message(self, format: str, *args: Any) -> None:
        if LOG_LEVEL.lower() in ("debug", "info"):
            try:
                super().log_message(format, *args)
            except Exception:
                pass

    def do_OPTIONS(self) -> None:
        origin = _origin_allowed(self.headers.get("Origin"))
        self.send_response(204)
        self.send_header("Connection", "close")
        if origin is not None:
            self.send_header("Access-Control-Allow-Origin", origin)
            self.send_header("Vary", "Origin")
            self.send_header("Access-Control-Allow-Credentials", "true")
            self.send_header("Access-Control-Allow-Methods",
                             "GET,POST,OPTIONS")
            self.send_header("Access-Control-Allow-Headers",
                             "Content-Type,Authorization")
            self.send_header("Access-Control-Max-Age", "86400")
        self.end_headers()

    def do_GET(self) -> None:
        origin = _origin_allowed(self.headers.get("Origin"))
        if self.path == "/health":
            payload = {
                "ok": True,
                "model": MODEL_ID,
                "max_completion_tokens": MAX_COMPLETION_TOKENS,
                "temperature": TEMPERATURE,
                "top_p": TOP_P,
                "clear_thinking": CLEAR_THINKING,
                "disable_reasoning": DISABLE_REASONING,
                "key_pool": pool.stats(),
            }
            _http_json(self, 200, payload, origin)
            return
        if self.path == "/":
            if os.path.isfile(STATIC_INDEX_PATH):
                _http_file(self, STATIC_INDEX_PATH, "text/html; charset=utf-8",
                           origin)
                return
            self.send_response(404)
            self.send_header("Connection", "close")
            if origin is not None:
                self.send_header("Access-Control-Allow-Origin", origin)
                self.send_header("Vary", "Origin")
                self.send_header("Access-Control-Allow-Credentials", "true")
                self.send_header("Access-Control-Allow-Methods",
                                 "GET,POST,OPTIONS")
                self.send_header("Access-Control-Allow-Headers",
                                 "Content-Type,Authorization")
            self.end_headers()
            return
        self.send_response(404)
        self.send_header("Connection", "close")
        if origin is not None:
            self.send_header("Access-Control-Allow-Origin", origin)
            self.send_header("Vary", "Origin")
            self.send_header("Access-Control-Allow-Credentials", "true")
            self.send_header("Access-Control-Allow-Methods",
                             "GET,POST,OPTIONS")
            self.send_header("Access-Control-Allow-Headers",
                             "Content-Type,Authorization")
        self.end_headers()

    def do_POST(self) -> None:
        origin = _origin_allowed(self.headers.get("Origin"))
        if self.path != "/api/chat":
            _http_error_json(self, 404, "not_found", "not found", origin)
            return
        try:
            raw = _read_body(self)
        except ValueError as e:
            msg = str(e)
            status = 413 if "too large" in msg else 400
            _http_error_json(self, status, "bad_request", msg, origin)
            return
        except Exception:
            _http_error_json(self, 400, "bad_request", "bad request", origin)
            return
        try:
            messages, user = _parse_chat_request(raw)
        except ValueError as e:
            msg = str(e)
            status = 413 if "too many" in msg or "too large" in msg else 422
            _http_error_json(self, status, "validation_error", msg, origin)
            return
        except Exception:
            _http_error_json(self, 422, "validation_error", "invalid request",
                             origin)
            return
        _stream_chat_to_client(self, messages, user, origin)


def main() -> None:
    if not API_KEYS:
        raise RuntimeError("No Cerebras API keys configured")
    httpd = ThreadingHTTPServer((HOST, PORT), AppHandler)
    try:
        httpd.serve_forever()
    finally:
        try:
            httpd.server_close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

