Ez a **tökéletes felállás**: Swift a telefonon (natív, szép, App Store-barát) és **V (Vlang)** a szerveren (brutálisan gyors, alacsony memóriahasználat).

Íme a Python kódod átirata **V nyelvre**, ami pontosan ugyanazt tudja: API kulcs forgatás, streaming proxy, hibatűrés (failover), CORS kezelés, de sokkal hatékonyabban.

### 1. A `replit.nix` fájl
Először ezt tedd be a `replit.nix`-be, hogy legyen V fordítód:

```nix
{ pkgs }: {
  deps = [
    pkgs.vlang
    pkgs.openssl
  ];
}
```

### 2. A szerver kód (`main.v`)
Másold ezt a `main.v` fájlba. Ez egyetlen fájl, nem kellenek külső csomagok, csak a standard könyvtár ("Batteries included").

```v
import os
import time
import json
import sync
import net.http
import net.urllib
import net.ssl

// --- Konfiguráció és Konstansok ---

const (
    model_id              = 'zai-glm-4.7'
    cerebras_host         = 'api.cerebras.ai'
    cerebras_path         = '/v1/chat/completions'
    default_port          = 8000
    max_request_bytes     = 2_000_000
    max_messages          = 2000
    max_message_chars     = 200_000
)

struct Config {
mut:
    allowed_origins []string
    port            int
    static_path     string
}

fn load_config() Config {
    mut c := Config{
        port: os.getenv('PORT').int()
        static_path: os.getenv_opt('STATIC_INDEX_PATH') or { 'index.html' }
    }
    if c.port == 0 { c.port = default_port }

    origins := os.getenv_opt('ALLOWED_ORIGINS') or { '*' }
    c.allowed_origins = origins.split(',').map(it.trim_space()).filter(it != '')

    return c
}

// --- API Kulcs Kezelés (Pool) ---

struct ApiKeyPool {
mut:
    keys            []string
    cooldowns       map[string]i64
    exhausted_until map[string]i64
    disabled        map[string]bool
    rr_index        int
    mu              sync.Mutex
}

fn new_api_pool() ?&ApiKeyPool {
    mut keys := []string{}

    // CEREBRAS_API_KEYS (comma separated)
    if packed := os.getenv_opt('CEREBRAS_API_KEYS') {
        parts := packed.split(',')
        for p in parts { if p.trim_space() != '' { keys << p.trim_space() } }
    }
    // CEREBRAS_API_KEY_1 ... 100
    for i in 1 .. 101 {
        if k := os.getenv_opt('CEREBRAS_API_KEY_${i}') {
            if k.trim_space() != '' { keys << k.trim_space() }
        }
    }
    // Single key
    if k := os.getenv_opt('CEREBRAS_API_KEY') {
        keys << k.trim_space()
    }

    // Unique keys only
    mut unique := []string{}
    for k in keys {
        if k !in unique { unique << k }
    }

    if unique.len == 0 { return error('No API keys found') }

    return &ApiKeyPool{
        keys: unique
        mu: sync.new_mutex()
    }
}

fn (mut p ApiKeyPool) acquire() ?string {
    p.mu.@lock()
    defer { p.mu.unlock() }

    now := time.now().unix()
    n := p.keys.len

    // Round Robin
    for _ in 0 .. n {
        idx := p.rr_index % n
        p.rr_index++
        key := p.keys[idx]

        if p.disabled[key] { continue }
        if now < p.cooldowns[key] { continue }
        if now < p.exhausted_until[key] { continue }

        return key
    }
    return error('No available keys (all cooled down or disabled)')
}

fn (mut p ApiKeyPool) mark_rate_limited(key string, seconds f64) {
    p.mu.@lock()
    defer { p.mu.unlock() }
    backoff := if seconds > 0 { i64(seconds) } else { 5 }
    p.cooldowns[key] = time.now().unix() + backoff
}

fn (mut p ApiKeyPool) mark_exhausted(key string, seconds f64) {
    p.mu.@lock()
    defer { p.mu.unlock() }
    backoff := if seconds > 0 { i64(seconds) } else { 86400 }
    p.exhausted_until[key] = time.now().unix() + backoff
}

fn (mut p ApiKeyPool) disable(key string) {
    p.mu.@lock()
    defer { p.mu.unlock() }
    p.disabled[key] = true
}

fn (mut p ApiKeyPool) stats() map[string]int {
    p.mu.@lock()
    defer { p.mu.unlock() }

    now := time.now().unix()
    mut available := 0
    mut disabled_cnt := 0

    for k in p.keys {
        if p.disabled[k] { 
            disabled_cnt++ 
            continue 
        }
        if now < p.cooldowns[k] { continue }
        if now < p.exhausted_until[k] { continue }
        available++
    }

    return {
        'total': p.keys.len
        'available': available
        'disabled': disabled_cnt
    }
}

// --- Adatstruktúrák ---

struct ChatMessage {
    role    string
    content string
}

struct ChatRequest {
    messages []ChatMessage
    user     string
}

struct OutgoingRequest {
    model                 string        [json: model]
    messages              []ChatMessage [json: messages]
    stream                bool          [json: stream]
    max_completion_tokens int           [json: max_completion_tokens]
    temperature           f64           [json: temperature]
    top_p                 f64           [json: top_p]
    user                  string        [json: user, omitempty]
}

// --- Segédfüggvények ---

fn get_retry_after(headers map[string]string) f64 {
    val := headers['retry-after'] 
    if val == '' { return 0.0 }
    return val.f64()
}

fn allow_cors(mut req http.Request, allowed []string) ?string {
    origin := req.header.get(.origin) or { '' }
    if origin == '' {
        if allowed.len == 1 && allowed[0] == '*' { return '*' }
        return none
    }
    if allowed.len == 1 && allowed[0] == '*' { return '*' }
    if origin in allowed { return origin }
    return none
}

// --- Handler ---

struct App {
mut:
    pool   &ApiKeyPool
    config Config
}

fn (mut app App) handle_request(mut req http.Request) http.Response {
    origin := allow_cors(mut req, app.config.allowed_origins) or { '' }

    mut headers := map[string]string{}
    if origin != '' {
        headers['Access-Control-Allow-Origin'] = origin
        headers['Access-Control-Allow-Credentials'] = 'true'
        headers['Vary'] = 'Origin'
    }

    if req.method == .options {
        headers['Access-Control-Allow-Methods'] = 'GET,POST,OPTIONS'
        headers['Access-Control-Allow-Headers'] = 'Content-Type,Authorization'
        return http.Response{ status: .no_content, header: http.new_header_from_map(headers) }
    }

    if req.method == .get {
        if req.url == '/health' {
            stats := app.pool.stats()
            body := json.encode({
                'ok': true, 
                'model': model_id,
                'pool': stats
            })
            headers['Content-Type'] = 'application/json'
            return http.Response{ body: body, status: .ok, header: http.new_header_from_map(headers) }
        }
        if req.url == '/' {
             // Serve static file if exists, simplistic approach
             if os.exists(app.config.static_path) {
                 content := os.read_file(app.config.static_path) or { '' }
                 headers['Content-Type'] = 'text/html'
                 return http.Response{ body: content, status: .ok, header: http.new_header_from_map(headers) }
             }
        }
        return http.Response{ status: .not_found, header: http.new_header_from_map(headers) }
    }

    if req.method == .post && req.url == '/api/chat' {
        return app.handle_chat(mut req, headers)
    }

    return http.Response{ status: .not_found, header: http.new_header_from_map(headers) }
}

fn (mut app App) handle_chat(mut req http.Request, base_headers map[string]string) http.Response {
    // 1. Validate Request
    if req.data.len > max_request_bytes {
        return http.Response{ status: .request_entity_too_large, body: '{"error":"too_large"}' }
    }

    raw_json := json.decode(map[string]json.Any, req.data) or {
        return http.Response{ status: .bad_request, body: '{"error":"invalid_json"}' }
    }

    // Extract messages manually to ensure types or use struct
    // Using loose decoding for safety
    msgs_any := raw_json['messages'] or { 
        return http.Response{ status: .unprocessable_entity, body: '{"error":"missing_messages"}' } 
    }

    // Construct outgoing messages
    mut out_msgs := []ChatMessage{}
    out_msgs << ChatMessage{ role: 'system', content: 'mindig magyarul válaszolj' }

    // Very basic parsing of the input messages
    arr := msgs_any.arr()
    if arr.len > max_messages {
        return http.Response{ status: .unprocessable_entity, body: '{"error":"too_many_messages"}' }
    }

    for m in arr {
        m_map := m.as_map()
        role := m_map['role'] or { json.Any('') }.str()
        content := m_map['content'] or { json.Any('') }.str()
        if content.len > max_message_chars {
             return http.Response{ status: .unprocessable_entity, body: '{"error":"message_too_large"}' }
        }
        out_msgs << ChatMessage{ role: role, content: content }
    }

    user := raw_json['user'] or { json.Any('') }.str()

    // 2. Prepare Upstream Request Payload
    payload := OutgoingRequest{
        model: model_id
        messages: out_msgs
        stream: true
        max_completion_tokens: 65000
        temperature: 1.0
        top_p: 0.95
        user: user
    }
    payload_json := json.encode(payload)

    // 3. Retry Logic & Streaming
    mut attempts := app.pool.keys.len
    if attempts < 1 { attempts = 1 }

    mut last_error := ''

    for _ in 0 .. attempts {
        api_key := app.pool.acquire() or {
            last_error = err.msg()
            break
        }

        // Connect directly via SSL to support streaming line-by-line
        mut conn := net.ssl.connect(cerebras_host, 443) or {
            app.pool.mark_rate_limited(api_key, 1.0)
            last_error = 'connection_failed'
            continue
        }

        // Construct Raw HTTP Request
        req_str := 'POST ${cerebras_path} HTTP/1.1\r\n' +
                   'Host: ${cerebras_host}\r\n' +
                   'Authorization: Bearer ${api_key}\r\n' +
                   'Content-Type: application/json\r\n' +
                   'Content-Length: ${payload_json.len}\r\n' +
                   'Connection: close\r\n\r\n' + 
                   payload_json

        conn.write_string(req_str) or {
            conn.close()
            continue
        }

        // Read Headers first
        mut reader := conn.new_reader()
        status_line := reader.read_line() or { '' }
        if !status_line.contains('200 OK') {
            // Error handling
            app.handle_upstream_error(api_key, status_line)
            conn.close()
            continue // Try next key
        }

        // If we are here, we have a 200 OK stream.
        // We need to return a generic "Hijack" or handle streaming manually.
        // V's net.http server is simple. We can't easily "stream" out from a handler 
        // that returns a simple http.Response object without blocking the whole memory.

        // TRICK: V's net.http doesn't support easy chunked streaming response in this simple mode.
        // However, since we are on Replit and need "immediate run", we will use a workaround:
        // We will read the stream, parse it, but we might have to buffer it if we use standard simple server.
        // FOR TRUE PERFORMANCE: We would write a custom TCP server loop. 
        // BUT for compatibility with the provided snippet style, let's try to stream.

        // NOTE: Standard V http server buffers response body. 
        // To do real streaming response in V, we need `req.connection.write()`. 
        // But `net.http` abstracts this.

        // **FALLBACK FOR SIMPLE SERVER:** 
        // Since V's standard HTTP server buffers, we will read the whole stream from Cerebras
        // (which is text), and send it back. For truly long streams this consumes RAM, 
        // but V handles strings efficiently. 
        // If you need REAL-TIME text appearing on iPhone, we need to bypass `http.Response`.
        // Let's assume for this specific code, buffering is acceptable OR we accept
        // that V's simple server waits for the handler.

        // WAIT! The user wants "brutally fast". Buffering destroys the "streaming" UX.
        // I will write a custom TCP handler loop below instead of using the high-level `handle_request`.
        // See `start_server` below.

        conn.close() // Placeholder logic here, real logic is in start_server
        break 
    }

    return http.Response{ status: .bad_gateway, body: '{"error":"upstream_failed"}' }
}

fn (mut app App) handle_upstream_error(key string, status_line string) {
    if status_line.contains('429') { app.pool.mark_rate_limited(key, 5.0) }
    else if status_line.contains('402') { app.pool.mark_exhausted(key, 86400.0) }
    else if status_line.contains('401') || status_line.contains('403') { app.pool.disable(key) }
}

// --- Custom Server Loop for True Streaming ---

fn start_fast_server(mut app App) {
    listener := net.listen_tcp(.ip6, ':${app.config.port}') or {
        net.listen_tcp(.ip, ':${app.config.port}') or { panic(err) }
    }
    println('Server running on :${app.config.port}')

    for {
        mut conn := listener.accept() or { continue }
        spawn handle_conn(mut conn, mut app)
    }
}

fn handle_conn(mut conn net.TcpConn, mut app App) {
    defer { conn.close() }
    conn.set_read_timeout(30 * time.second)

    // Read request (simplified HTTP parser)
    mut reader := conn.new_reader()
    line := reader.read_line() or { return }
    parts := line.split(' ')
    if parts.len < 2 { return }
    method := parts[0]
    path := parts[1]

    // Read headers
    mut content_length := 0
    mut origin := ''
    for {
        h := reader.read_line() or { break }
        if h == '' || h == '\r' { break }
        if h.to_lower().starts_with('content-length:') {
            content_length = h.all_after(':').trim_space().int()
        }
        if h.to_lower().starts_with('origin:') {
            origin = h.all_after(':').trim_space()
        }
    }

    // CORS Checks
    mut allowed := false
    allowed_origin := if app.config.allowed_origins.len == 1 && app.config.allowed_origins[0] == '*' { 
        '*' 
    } else {
        if origin in app.config.allowed_origins { origin } else { '' }
    }

    if allowed_origin != '' { allowed = true }

    // Headers helper
    send_headers := fn [mut conn, allowed, allowed_origin] (status string, content_type string) {
        conn.write_string('HTTP/1.1 ${status}\r\n') or {}
        conn.write_string('Content-Type: ${content_type}\r\n') or {}
        if allowed {
            conn.write_string('Access-Control-Allow-Origin: ${allowed_origin}\r\n') or {}
            conn.write_string('Access-Control-Allow-Credentials: true\r\n') or {}
        }
        conn.write_string('Connection: close\r\n\r\n') or {}
    }

    // Routing
    if method == 'OPTIONS' {
        conn.write_string('HTTP/1.1 204 No Content\r\n') or {}
        if allowed {
            conn.write_string('Access-Control-Allow-Origin: ${allowed_origin}\r\n') or {}
            conn.write_string('Access-Control-Allow-Methods: GET,POST,OPTIONS\r\n') or {}
            conn.write_string('Access-Control-Allow-Headers: Content-Type,Authorization\r\n') or {}
        }
        conn.write_string('\r\n') or {}
        return
    }

    if path == '/health' {
        stats := app.pool.stats()
        json_resp := json.encode({'ok': true, 'model': model_id, 'pool': stats})
        send_headers('200 OK', 'application/json')
        conn.write_string(json_resp) or {}
        return
    }

    if path != '/api/chat' || method != 'POST' {
        send_headers('404 Not Found', 'application/json')
        conn.write_string('{"error":"not_found"}') or {}
        return
    }

    // Read Body
    if content_length > max_request_bytes {
        send_headers('413 Payload Too Large', 'application/json')
        return
    }
    mut body_buf := []u8{len: content_length}
    reader.read(mut body_buf) or { return }
    body_str := body_buf.bytestr()

    // Parse JSON
    req_json := json.decode(map[string]json.Any, body_str) or {
        send_headers('400 Bad Request', 'application/json')
        return
    }

    // Prepare Upstream
